1	#!/usr/bin/env node
2	// World-scope conformance runner (see DESIGN.md): the rules that audit repo
3	// state as it exists now, plus the pack-agnostic settings/load integrity
4	// diagnostics (malformed config, an unknown pack, a broken pack.mjs). Rules that
5	// judge the current change (`scope: 'work'`) run in check_the_work.mjs, which
6	// this file shares no code with — only the scope-blind mechanism helpers
7	// (run-active-pack-rules.mjs, report-findings.mjs). It names NO pack: adoption
8	// interview hygiene is a skill-owned check that rides its own pack's activation,
9	// and a malformed `questions` field is a load fault the pack registry reports.
10	// Wired into the project's test/CI flow, not the Stop hook. Dependency-free Node ≥18.
11	//   (default)   whole-repo sweep — milliseconds on a text corpus, sees cross-file breakage
12	//   --changed   transitional: scope to files changed vs the merge-base with main
13	//               (adopting a repo with a backlog only — not the enforcement default)
14	//   --base REF  override the base ref
15	//   --list      machine-readable catalog of every rule, both scopes (id, severity, description, doc)
16	//   --init      write .claudinite-checks.json — basics plus the fingerprinted packs
17	import { writeFileSync, existsSync } from 'node:fs';
18	import { join } from 'node:path';
19	import { buildContext } from './helpers/repo-context.mjs';
20	import { discoverPacks, resolveDeclaredPacks } from '../pack_loader/pack-registry.mjs';
21	import { runActivePackRules, packRules } from './run-active-pack-rules.mjs';
22	import { reportFindings } from './report-findings.mjs';
23	
24	const configError = (what, fix) => ({
25	  rule: 'config', severity: 'blocking', file: '.claudinite-checks.json', line: null,
26	  what, why: 'the settings file is what executes — a bad key, value, or pack name silently changes what runs', fix, doc: 'engine/checks/README.md',
27	});
28	
29	const args = process.argv.slice(2);
30	const has = (flag) => args.includes(flag);
31	const value = (flag) => (args.includes(flag) ? args[args.indexOf(flag) + 1] : null);
32	const root = value('--root') || process.cwd();
33	
34	if (has('--list')) {
35	  const { packs } = await discoverPacks({ localRoot: root });
36	  for (const r of packRules(packs)) {
37	    console.log(`${r.id}\t${r.severity}\t${r.description}\t${r.doc}`);
38	  }
39	  process.exit(0);
40	}
41	
42	if (has('--init')) {
43	  const path = join(root, '.claudinite-checks.json');
44	  if (existsSync(path)) {
45	    console.log(`${path} already exists — leaving it as-is.`);
46	    process.exit(0);
47	  }
48	  const { packs } = await discoverPacks({ localRoot: root });
49	  const ctx = buildContext({ root, mode: 'all' });
50	  // No pack is active by default, so the baseline is seeded as an explicit
51	  // declaration alongside the fingerprinted packs: every pack that flags
52	  // `seededByDefault` is written in (discovered structurally — the engine names
53	  // no pack), plus the ones a fingerprint detects. A seeded pack is still
54	  // opt-out-able where its own policy allows (baselining re-adds only the packs
55	  // whose absence it treats as drift), so removing a seeded declaration can
56	  // stick; each seeded pack ships its own one-time seed migration for the fleet.
57	  // Local packs are declared by hand, never fingerprinted or seeded — exclude
58	  // them from --init's seeding so a repo that already carries local packs (but
59	  // no config yet) doesn't auto-declare them.
60	  const seeded = packs.filter((p) => p.seededByDefault && !p.local).map((p) => p.id);
61	  const detected = [...seeded, ...packs.filter((p) => p.detect && !p.local && p.detect(ctx)).map((p) => p.id)];
62	  // A pack can't be imported without its dependencies — pull each declared pack's
63	  // `requires` closure into the declaration so it's complete and visible.
64	  const declared = resolveDeclaredPacks(detected, packs);
65	  // maintenance.delivery is deliberately materialized, not defaulted — the selection
66	  // must be visible in the file where a project would change it (see engine/checks/README.md).
67	  // Only what carries a decision: the declaration and the always-explicit
68	  // delivery. Empty rules/accept boilerplate is noise, not settings (#385);
69	  // loadConfig defaults absent keys.
70	  writeFileSync(path, `${JSON.stringify({ packs: declared, maintenance: { delivery: 'auto-merge' } }, null, 2)}\n`);
71	  console.log(`Wrote ${path} (packs: ${declared.join(', ')}).`);
72	  // The adoption interview (surfacing each declared pack's pending questions) is
73	  // driven by the adopt-claudinite skill / bootstrap.md, and nudged every session
74	  // by the SessionStart interview-check step — not printed here, so this runner
75	  // imports no pack.
76	  process.exit(0);
77	}
78	
79	const { packs, errors: packErrors } = await discoverPacks({ localRoot: root });
80	const ctx = buildContext({ root, mode: has('--changed') ? 'changed' : 'all', baseOverride: value('--base') });
81	
82	// Settings/load integrity — pack-agnostic, so the world runner owns them.
83	// Settings validity is checked at load: malformed JSON, an unknown
84	// property, and a wrong pack name are all equally settings errors. loadConfig
85	// reports the first two; the runner adds unknown pack names (only it holds the
86	// registry) and broken/duplicate local pack.mjs faults.
87	const findings = [];
88	for (const e of ctx.config.errors) findings.push(configError(e.what, e.fix));
89	for (const e of packErrors) findings.push(configError(e.what, e.fix));
90	// knownIds spans canon AND local packs, so a declared local pack id is valid and
91	// the unknown-pack message lists it among the declarable packs. ctx.config.packs
92	// is loadConfig's normalized view — bare ids, a namespaced local_packs/<name>
93	// declaration already resolved through packEntryId.
94	const knownIds = new Set(packs.map((p) => p.id));
95	for (const name of ctx.config.packs) {
96	  if (typeof name === 'string' && !knownIds.has(name)) {
97	    findings.push(configError(`declares unknown pack "${name}"`, `remove it or fix the name — declarable packs: ${[...knownIds].sort().join(', ')}`));
98	  }
99	}
100	// (Adoption-interview hygiene is a skill-owned check that runs below with the
101	// other active-pack rules; a malformed `questions` field arrives as a load fault
102	// in packErrors above. Neither names a pack here.)
103	
104	// The world rules: everything not scoped to the work. A broken contributedRules
105	// seam is a config-level fault surfaced here (the world runner owns diagnostics).
106	findings.push(...runActivePackRules(ctx, packs, {
107	  includeRule: (rule) => rule.scope !== 'work',
108	  onContributeError: (pack, e) => findings.push(configError(
109	    `the "${pack.id}" pack's contributedRules failed: ${e.message}`, 'fix the pack manifest, or the contribution it interprets')),
110	}));
111	
112	const blocking = reportFindings(findings, ctx.config, { scopeLabel: 'world', mode: ctx.mode, baseRef: ctx.baseRef });
113	process.exit(blocking ? 1 : 0);
