1	import { dirname, join, normalize } from 'node:path';
2	import { humanTurns, assistantTextAfter, classificationLine, classesIn } from './session-transcript.mjs';
3	import { addedLines } from './line-scanning.mjs';
4	import { extractLinks } from './markdown.mjs';
5	
6	// The fluent check-the-work surface over ctx. Every accessor is null-safe — no
7	// transcript, no merge-base, an empty branch all yield empty results — so a rule
8	// reads as one chain with no guard ladders. Mechanism only: a rule still owns
9	// its patterns, file filters, and failure text.
10	//
11	// A rule declaring `scope: 'work'` receives this object as its `run` argument
12	// (runRule dispatches); check-the-world rules keep the raw ctx until a fluent
13	// world object exists. The raw surface a work rule still needs (files, read,
14	// exists, …) is delegated here, so a work rule — and the structural helpers it
15	// calls, e.g. findExtensionManifest — never touches ctx itself.
16	export const work = (ctx) => new Work(ctx);
17	
18	// The single dispatch seam: the runner and every rule test invoke rules through
19	// this, so a rule's scope decides its context in exactly one place. Extra args
20	// pass through (some rules take test-only options after the context).
21	export const runRule = (rule, ctx, ...args) => rule.run(rule.scope === 'work' ? work(ctx) : ctx, ...args);
22	
23	// Null-object for "no such turn": every accessor answers emptily, so a chain
24	// ending in .last() never needs an existence guard before its predicates.
25	const NO_TURN = {
26	  exists: false, text: '', timestamp: null,
27	  excerpt: () => '', reply: () => '', classified: () => false,
28	  classes: () => new Set(), time: () => 0,
29	};
30	
31	class Turn {
32	  constructor(entries, { index, timestamp, text }) {
33	    this.entries = entries;
34	    this.index = index;
35	    this.timestamp = timestamp;
36	    this.text = text;
37	    this.exists = true;
38	  }
39	
40	  excerpt(n) { return this.text.replace(/\s+/g, ' ').slice(0, n); }
41	  reply() { return assistantTextAfter(this.entries, this.index); }
42	  classified() { return classificationLine(this.reply()) !== null; }
43	  classes() { return classesIn(classificationLine(this.reply())); }
44	  time() { return Date.parse(this.timestamp ?? '') || 0; }
45	}
46	
47	// Array subclass so filter/map stay chainable and .last() survives them.
48	class Turns extends Array {
49	  last() { return this.length ? this[this.length - 1] : NO_TURN; }
50	}
51	
52	class Conversation {
53	  constructor(entries) { this.entries = entries ?? []; }
54	
55	  ownerTurns() {
56	    const turns = new Turns();
57	    for (const t of humanTurns(this.entries)) turns.push(new Turn(this.entries, t));
58	    return turns;
59	  }
60	}
61	
62	class Work {
63	  constructor(ctx) { this.ctx = ctx; }
64	
65	  get branch() { return this.ctx.branch; }
66	  get baseRef() { return this.ctx.baseRef; }
67	  get commits() { return this.ctx.commits; }
68	  get files() { return this.ctx.files; }
69	  get changedFiles() { return this.ctx.changedFiles; }
70	  get tracked() { return this.ctx.tracked; }
71	  // The discovered pack objects (runner-attached) and the normalized config —
72	  // the pair a rule that reasons over pack metadata (e.g. adoption-interview
73	  // state) hands to the interview helpers, without reaching into ctx itself.
74	  get packs() { return this.ctx.packs ?? []; }
75	  get config() { return this.ctx.config; }
76	  read(path) { return this.ctx.read(path); }
77	  readBase(path) { return this.ctx.readBase(path); }
78	  exists(path) { return this.ctx.exists(path); }
79	  packConfig(id) { return this.ctx.config?.packConfig?.[id]; }
80	
81	  conversation() { return new Conversation(this.ctx.conversation()); }
82	
83	  addedLines(files) { return addedLines(this.ctx, files ?? this.ctx.changedFiles); }
84	
85	  onDefaultBranch() { return this.ctx.branch === 'main' || this.ctx.branch === 'master'; }
86	
87	  introducedMerges() { return this.ctx.introducedMergeCommits(); }
88	
89	  // Branch commits since the merge-base, oldest first, each with a parsed .time.
90	  branchCommits() {
91	    return this.ctx.commitsWithFiles().map((c) => ({ ...c, time: Date.parse(c.date) || 0 }));
92	  }
93	
94	  // `file` parsed as JSON at head and at the scoping base; a side that is
95	  // absent or unparsable is null, so set-vs-base rules need no try/catch.
96	  jsonPair(file) {
97	    const parse = (text) => {
98	      if (text === null) return null;
99	      try { return JSON.parse(text); } catch { return null; }
100	    };
101	    return { head: parse(this.ctx.read(file)), base: parse(this.ctx.readBase(file)) };
102	  }
103	
104	  filesContaining(needle, files = this.ctx.files) {
105	    return files.filter((f) => (this.ctx.read(f) ?? '').includes(needle));
106	  }
107	
108	  // Relative Markdown links that resolve to nothing: [{ file, line, target, resolved }].
109	  // Links reaching outside the repo aren't verifiable here and are skipped.
110	  deadLinks(files) {
111	    const out = [];
112	    for (const file of (files ?? this.ctx.files).filter((f) => f.endsWith('.md'))) {
113	      const text = this.ctx.read(file);
114	      if (text === null) continue;
115	      for (const { target, line } of extractLinks(text)) {
116	        const resolved = normalize(join(dirname(file), target));
117	        if (resolved.startsWith('..') || this.ctx.exists(resolved)) continue;
118	        out.push({ file, line, target, resolved });
119	      }
120	    }
121	    return out;
122	  }
123	
124	  // Tracked lines still naming a path this change deletes: [{ file, line, text, gone }].
125	  // A hit whose every occurrence widens to a path token that still resolves is a
126	  // rename that kept the basename, not a dangling reference — dropped. `tolerated(gone)`
127	  // lets the rule exempt paths something else deliberately governs.
128	  danglingReferences(tolerated = () => false) {
129	    const out = [];
130	    for (const gone of this.ctx.deleted) {
131	      if (tolerated(gone)) continue;
132	      for (const hit of this.ctx.grepTracked(gone)) {
133	        if (hit.file === gone || referencesSurvivingPath(hit, gone, this.ctx)) continue;
134	        out.push({ ...hit, gone });
135	      }
136	    }
137	    return out;
138	  }
139	}
140	
141	const PATH_CHAR = /[\w./@-]/;
142	
143	function widenToken(text, start, end) {
144	  let s = start;
145	  let e = end;
146	  while (s > 0 && PATH_CHAR.test(text[s - 1])) s--;
147	  while (e < text.length && PATH_CHAR.test(text[e])) e++;
148	  return text.slice(s, e);
149	}
150	
151	function referencesSurvivingPath(hit, gone, ctx) {
152	  let idx = hit.text.indexOf(gone);
153	  if (idx === -1) return false;
154	  while (idx !== -1) {
155	    const token = widenToken(hit.text, idx, idx + gone.length);
156	    const resolved = normalize(join(dirname(hit.file), token));
157	    if (!((token !== gone && ctx.exists(token)) || ctx.exists(resolved))) return false;
158	    idx = hit.text.indexOf(gone, idx + 1);
159	  }
160	  return true;
161	}
