3	// Corpus-integrity rule: the pack catalog README must list every pack on
4	// disk, so the hand-maintained index can't silently drift behind a newly
5	// added pack (it has, twice). Only meaningful in the Claudinite repo itself;
6	// a consumer tracks no registry (the corpus lives under its shared mount).
7	// Skills have no catalog of their own (#385): a skill is its owning pack's
8	// content, listed nowhere but its pack.
9	//
10	// The membership token is the pack DIRECTORY, not a README inside it: a pack
11	// whose whole README was the checks-and-skills table the manifest now carries
12	// has no README at all, and the catalog still has to list it.
13	const CATALOGS = [
14	  { kind: 'pack', member: /^packs\/([^/]+)\/pack\.mjs$/, readme: 'packs/README.md', token: (n) => `(${n}/` },
15	];
16	
17	const rule = {
18	  id: 'catalog-completeness',
19	  severity: 'blocking',
20	  description: 'packs/README.md lists every packs/<name>/',
21	  doc: 'packs/README.md',
22	  why: 'a hand-maintained catalog that omits a real pack misroutes readers and hides capability; the check keeps the index honest against the tree',
23	
24	  run(ctx) {
25	    if (!ctx.tracked.includes('engine/pack_loader/pack-registry.mjs')) {
26	      return [];
27	    }
28	    const out = [];
29	    for (const { kind, member, readme, token } of CATALOGS) {
30	      const text = ctx.read(readme);
31	      if (text === null) continue;
32	      const names = new Set();
33	      for (const f of ctx.tracked) {
34	        const m = member.exec(f);
35	        if (m) names.add(m[1]);
36	      }
37	      for (const name of [...names].sort()) {
38	        if (!text.includes(token(name))) {
39	          out.push(finding(rule, {
40	            file: readme,
41	            what: `the ${kind} "${name}" exists on disk but is not listed in ${readme}`,
42	            fix: `add a "${name}" entry to ${readme} (or delete the ${kind} if it is dead)`,
43	          }));
44	        }
45	      }
46	    }
47	    return out;
48	  },
49	};
