33	        line: null,
34	        what: `acceptance for ${f.rule}${acceptance.path ? ` on ${acceptance.path}` : ''}${acceptance.pack ? ` (on the "${acceptance.pack}" pack entry)` : ''} has no reason`,
35	        why: 'the reason string is what makes an accepted violation reviewable',
36	        fix: 'add a non-empty "reason" to the acceptance entry',
