1	// THE PACK MANIFEST SPEC — the single declarative statement of what a
2	// `pack.mjs` may and must carry. Everything a pack declares about itself is
3	// described here once, and `validateManifest` is the only thing that judges a
4	// manifest against it. The loader calls it on every pack it imports (canon and a
5	// consumer's own `local_packs/` alike), so a malformed or incomplete manifest
6	// surfaces as a blocking `config` error at load — the same class as invalid JSON
7	// in `.claudinite-checks.json`.
8	//
9	// WHY A SPEC AND NOT A CHECK. A required manifest field is part of the pack
10	// contract, not a conformance opinion about a repo's content: a conformance rule
11	// would have to be declared BY a pack, run only when that pack is active, and
12	// re-derive the manifest by reading its source text — enforcing the shape of the
13	// system from inside one of its members. The spec is upstream of every pack, so
14	// there is nothing to declare and nothing to parse.
15	//
16	// Dependency-free by the engine's module rule: no imports, no filesystem. The
17	// caller supplies the facts from disk (the `skills/` directory listing), so this
18	// module is pure and testable standalone.
19	
20	// The routing budget. Both sides of `ruleRoutingGuidance` are emitted as one row
21	// of a table every session loads (engine/pack_loader/inject-pack-prose.mjs), so
22	// the cap is a context cost, not a style preference: enough for a boundary and a
23	// pointer to the pack that owns the other side.
24	export const MAX_ROUTING_WORDS = 20;
25	
26	// The two conformance scopes. A rule's scope is its PLACEMENT on the manifest —
27	// `worldRules` audit repo state, `workRules` judge the change and session in
28	// front of you — so the two runners' partition is declared where a reader of the
29	// pack can see it, and a rule module never restates (or contradicts) it.
30	export const RULE_SCOPES = { worldRules: 'world', workRules: 'work' };
31	
32	const isPlainObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
33	const isStringArray = (v) => Array.isArray(v) && v.every((x) => typeof x === 'string');
34	const isRuleArray = (v) => Array.isArray(v) && v.every((x) => isPlainObject(x) && typeof x.id === 'string' && typeof x.run === 'function');
35	
36	// Every field a manifest may carry. `required` fields must be present; the rest
37	// are validated only when declared. An UNDECLARED field is an error: the spec is
38	// the closed vocabulary of a pack, so a typo (`rule:`, `skill:`) fails loudly
39	// instead of being silently ignored forever.
40	export const PACK_FIELDS = {
41	  id: { required: true, describe: 'the pack id, matching its directory name', valid: (v) => typeof v === 'string' && v.length > 0 },
42	  ruleRoutingGuidance: { required: true, describe: 'what belongs in this pack and what does not, each at most 20 words', valid: isPlainObject },
43	  badge: { describe: 'the pack badge filename, resolved off the pack directory', valid: (v) => typeof v === 'string' },
44	  detect: { describe: 'a fingerprint predicate over the repo context, or null', valid: (v) => v === null || typeof v === 'function' },
45	  marker: { describe: 'a human-readable glob naming what detect looks for, or null', valid: (v) => v === null || typeof v === 'string' },
46	  prose: { describe: 'the RULES.md filename injected at session start, or null', valid: (v) => v === null || typeof v === 'string' },
47	  seededByDefault: { describe: 'whether bootstrap --init seeds this pack everywhere', valid: (v) => typeof v === 'boolean' },
48	  requires: { describe: 'pack ids this pack depends on, resolved when the declaration is written', valid: isStringArray },
49	  contributes: { describe: 'rules addressed to another pack, keyed by that pack id', valid: isPlainObject },
50	  contributedRules: { describe: 'the seam interpreting other packs contributions to this one', valid: (v) => typeof v === 'function' },
51	  env: { describe: 'environment requirements the pack needs to run its checks', valid: isPlainObject },
52	  questions: { describe: 'the pack adoption-interview questions', valid: (v) => Array.isArray(v) },
53	  skills: { describe: 'the skill directory names bundled under this pack skills/', valid: isStringArray },
54	  worldRules: { describe: 'rules auditing repo state (check_the_world)', valid: isRuleArray },
55	  workRules: { describe: 'rules judging the current change and session (check_the_work)', valid: isRuleArray },
56	};
57	
58	const REQUIRED = Object.entries(PACK_FIELDS).filter(([, f]) => f.required).map(([k]) => k);
59	
60	const wordCount = (s) => s.trim().split(/\s+/).filter(Boolean).length;
61	
62	// Validate one manifest against the spec. `skillDirs` is the list of directory
63	// names under `<pack>/skills/` (the caller reads it; this module touches no
64	// disk). Returns `{ what, fix }` errors — the loader's error shape — never
65	// throws, so one bad manifest can't sink the run.
66	export function validateManifest(mod, { label, skillDirs = [] } = {}) {
67	  const errors = [];
68	  const at = label ? `${label}: ` : '';
69	  const err = (what, fix) => errors.push({ what: `${at}${what}`, fix });
70	
71	  if (!isPlainObject(mod)) {
72	    err('the pack has no object default export', 'export default { id, ruleRoutingGuidance, ... } from its pack.mjs');
73	    return errors;
74	  }
75	
76	  for (const key of REQUIRED) {
77	    if (!(key in mod)) err(`declares no "${key}"`, `add "${key}" — ${PACK_FIELDS[key].describe}`);
78	  }
79	  for (const [key, value] of Object.entries(mod)) {
80	    const field = PACK_FIELDS[key];
81	    if (!field) {
82	      err(`declares "${key}", which is not a pack manifest field`, `remove it, or add it to the spec in engine/pack_loader/pack-schema.mjs — the known fields are: ${Object.keys(PACK_FIELDS).join(', ')}`);
83	      continue;
84	    }
85	    if (!field.valid(value)) err(`"${key}" is not a valid value`, `${key} is ${field.describe}`);
86	  }
87	
88	  if (isPlainObject(mod.ruleRoutingGuidance)) {
89	    for (const side of ['belongs', 'excludes']) {
90	      const v = mod.ruleRoutingGuidance[side];
91	      if (typeof v !== 'string' || !v.trim()) {
92	        err(`ruleRoutingGuidance declares no "${side}"`, side === 'belongs'
93	          ? 'state the kind of content this pack owns, in at most 20 words'
94	          : 'state what belongs elsewhere and which pack owns it, in at most 20 words');
95	        continue;
96	      }
97	      const n = wordCount(v);
98	      if (n > MAX_ROUTING_WORDS) {
99	        err(`ruleRoutingGuidance.${side} is ${n} words, over the ${MAX_ROUTING_WORDS}-word cap`,
100	          `cut it to ${MAX_ROUTING_WORDS} words — it is one row of a table every session loads`);
101	      }
102	    }
103	  }
104	
105	  // A rule's scope is where it is declared; the manifest is the authority. A
106	  // rule module may still carry `scope` for the dispatch seam that reads it off
107	  // the rule object (engine/checks/helpers/work.mjs — which hands a work rule
108	  // its fluent surface), but then the two must AGREE: a module that says one
109	  // thing while the list it sits in says another is drift with a wrong context
110	  // waiting at the end of it.
111	  for (const [key, scope] of Object.entries(RULE_SCOPES)) {
112	    if (!isRuleArray(mod[key])) continue;
113	    for (const rule of mod[key]) {
114	      if ('scope' in rule && rule.scope !== scope) {
115	        err(`the rule "${rule.id}" declares scope "${rule.scope}" but sits in ${key}`,
116	          `move the rule to the list matching its scope, or drop its "scope" field — the manifest decides`);
117	      }
118	    }
119	  }
120	
121	  // The bundled-skills declaration and the tree must agree in BOTH directions:
122	  // an undeclared directory is a skill nothing announces, and a declared name
123	  // with no directory is a manifest that lies.
124	  if (isStringArray(mod.skills)) {
125	    for (const name of mod.skills) {
126	      if (!skillDirs.includes(name)) err(`declares a skill "${name}" with no skills/${name}/ directory`, `create skills/${name}/SKILL.md, or drop the declaration`);
127	    }
128	  }
129	  for (const dir of skillDirs) {
130	    if (!(mod.skills ?? []).includes(dir)) err(`bundles skills/${dir}/ but does not declare it`, `add "${dir}" to the pack's "skills" list`);
131	  }
132	
133	  return errors;
134	}
135	
136	// The manifest as the rest of the engine consumes it: the two scoped rule lists
137	// flattened into the single `rules` array every runner already walks, each rule
138	// stamped with the scope its placement declared. One derivation, here — nothing
139	// downstream re-decides a rule's scope.
140	export function normalizeManifest(mod) {
141	  const rules = [];
142	  for (const [key, scope] of Object.entries(RULE_SCOPES)) {
143	    for (const rule of mod[key] ?? []) rules.push({ ...rule, scope });
144	  }
145	  return { ...mod, rules };
146	}
